<?php
class TransactionController extends Controller {
    public function index(): void { Auth::requireLogin(); $uid=Auth::user()['id']; $page=max(1,(int)($_GET['page']??1)); $per=15; $this->render('dashboard/transactions',['transactions'=>Transaction::all($uid,$per,($page-1)*$per),'page'=>$page,'hasMore'=>Transaction::count($uid)>$page*$per]); }
    public function save(): void { Auth::requireLogin();$this->verifyCsrf();$uid=Auth::user()['id'];$d=['type'=>$_POST['type']??'expense','amount'=>(float)($_POST['amount']??0),'category'=>trim($_POST['category']??''),'payment_method'=>trim($_POST['payment_method']??''),'date'=>$_POST['date']??date('Y-m-d'),'description'=>trim($_POST['description']??'')];if($d['amount']<=0||!in_array($d['type'],['income','expense'],true)||!$d['category']){$this->flash('error','Revisa el tipo, monto y categoría.');}else{Transaction::create($uid,$d);$this->flash('success','Movimiento registrado.');}$this->redirect('index.php?url=dashboard'); }
    public function edit(): void { Auth::requireLogin();$uid=Auth::user()['id'];$id=(int)($_GET['id']??0);$tx=Transaction::find($id,$uid);if(!$tx){$this->flash('error','Movimiento no encontrado.');$this->redirect('index.php?url=dashboard');}if($_SERVER['REQUEST_METHOD']==='POST'){$this->verifyCsrf();$d=['type'=>$_POST['type'],'amount'=>(float)$_POST['amount'],'category'=>trim($_POST['category']),'payment_method'=>trim($_POST['payment_method']),'date'=>$_POST['date'],'description'=>trim($_POST['description']??'')];Transaction::update($id,$uid,$d);$this->flash('success','Movimiento actualizado.');$this->redirect('index.php?url=dashboard');}$this->render('dashboard/edit',['tx'=>$tx,'csrf'=>$this->csrf()]); }
    public function delete(): void { Auth::requireLogin();$this->verifyCsrf();Transaction::delete((int)$_POST['id'],Auth::user()['id']);$this->flash('success','Movimiento eliminado.');$this->redirect('index.php?url=dashboard'); }
}
